// Shared loader for the evaluation scripts: joins every eval folder's postings with its gold labels.
//
// Postings come from eval/<name>/postings.jsonl and from eval/<name>/description-only/*/postings.jsonl
// (generated by `npm run eval:build` or committed with the batch). Gold labels come from the same
// folder's labels/adjudicated.jsonl if it exists, otherwise labels/<name>.jsonl for the folder's owner.
// Postings with no label are skipped and counted.
import { readFileSync, readdirSync, existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';

export const LABELS = ['sponsors', 'does_not_sponsor', 'silent', 'unclear'];
export const DEV_IDS_PATH = 'eval/dev_ids.txt';

export const readJsonl = (p) =>
  readFileSync(p, 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l));

export function writeJsonl(p, rows) {
  mkdirSync(dirname(p), { recursive: true });
  writeFileSync(p, rows.map((r) => JSON.stringify(r) + '\n').join(''));
}

function postingDirs(root) {
  const dirs = [];
  for (const d of readdirSync(root, { withFileTypes: true })) {
    if (!d.isDirectory()) continue;
    const base = join(root, d.name);
    if (existsSync(join(base, 'postings.jsonl'))) dirs.push({ dir: base, owner: d.name });
    const sub = join(base, 'description-only');
    if (existsSync(sub)) {
      for (const s of readdirSync(sub, { withFileTypes: true })) {
        if (s.isDirectory() && existsSync(join(sub, s.name, 'postings.jsonl'))) {
          dirs.push({ dir: join(sub, s.name), owner: d.name });
        }
      }
    }
  }
  return dirs;
}

// Returns { items, unlabeled, problems }. Each item has the posting fields plus
// gold (label), quote, seen_model_output, pilot, set (folder), owner, text_kind.
export function loadEvalSet({ root = 'eval', includePilot = false } = {}) {
  const items = [];
  const unlabeled = [];
  const problems = [];
  const seen = new Map();
  for (const { dir, owner } of postingDirs(root)) {
    const adjudicated = join(dir, 'labels', 'adjudicated.jsonl');
    const ownerFile = join(dir, 'labels', `${owner}.jsonl`);
    const labelFile = existsSync(adjudicated) ? adjudicated : ownerFile;
    const labels = new Map();
    if (existsSync(labelFile)) for (const l of readJsonl(labelFile)) labels.set(l.id, l);
    for (const p of readJsonl(join(dir, 'postings.jsonl'))) {
      if (seen.has(p.id)) problems.push(`${p.id}: in both ${seen.get(p.id)} and ${dir}`);
      seen.set(p.id, dir);
      const l = labels.get(p.id);
      if (!l) {
        unlabeled.push(p.id);
        continue;
      }
      if (!LABELS.includes(l.label)) {
        problems.push(`${p.id}: invalid label ${l.label}`);
        continue;
      }
      const pilot = l.seen_model_output !== false;
      if (pilot && !includePilot) continue;
      items.push({
        ...p,
        gold: l.label,
        quote: l.quote,
        seen_model_output: l.seen_model_output,
        pilot,
        set: dir,
        owner,
        text_kind: p.text_raw ? 'raw+posting' : 'posting-only',
      });
    }
  }
  items.sort((a, b) => a.id.localeCompare(b.id));
  return { items, unlabeled, problems };
}

export function loadDevIds() {
  if (!existsSync(DEV_IDS_PATH)) return null;
  return new Set(readFileSync(DEV_IDS_PATH, 'utf8').split('\n').map((s) => s.trim()).filter((s) => s && !s.startsWith('#')));
}

// split: 'dev' | 'test' | 'all'. 'dev' and 'test' need eval/dev_ids.txt.
export function selectSplit(items, split) {
  if (split === 'all') return items;
  const dev = loadDevIds();
  if (!dev) throw new Error(`${DEV_IDS_PATH} does not exist. Create it with: npm run eval:dev -- --write`);
  return items.filter((i) => (split === 'dev' ? dev.has(i.id) : !dev.has(i.id)));
}

// Deterministic seeded random numbers, so a dev set can be reproduced from its seed.
function xmur3(str) {
  let h = 1779033703 ^ str.length;
  for (let i = 0; i < str.length; i++) {
    h = Math.imul(h ^ str.charCodeAt(i), 3432918353);
    h = (h << 13) | (h >>> 19);
  }
  return () => {
    h = Math.imul(h ^ (h >>> 16), 2246822507);
    h = Math.imul(h ^ (h >>> 13), 3266489909);
    return (h ^= h >>> 16) >>> 0;
  };
}
export function seededRandom(seed) {
  let a = xmur3(String(seed))();
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
export function shuffle(arr, rand) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

export function parseArgs(argv) {
  const out = {};
  for (let i = 0; i < argv.length; i++) {
    if (!argv[i].startsWith('--')) continue;
    const key = argv[i].slice(2);
    const next = argv[i + 1];
    if (next === undefined || next.startsWith('--')) out[key] = true;
    else {
      out[key] = next;
      i++;
    }
  }
  return out;
}
